        s = sum(nums1)
        d = sum(nums2)

        if s <= x:
            return 0

        ind = sorted(range(n), key=lambda i: nums2[i])
        dp = [0] * (n + 1)
        r = n + 1

        for i in range(1, n + 1):
            for j in range(min(i, r - 1), 0, -1):
                dp[j] = max(dp[j], dp[j - 1] + nums2[ind[i - 1]] * nums1[ind[i - 1]])
                if s + d - dp[j] <= x:
                    r = min(r, j)

        return r if r <= n else -1

from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        if not word:
            return 0

        forbidden_set = set(forbidden)
        res = 0
        n = len(word)

        for left in range(n):
            for right in range(left, n):
                if word[left:right + 1] in forbidden_set:
                    break
            else:
                res = max(res, right - left)

        return res
